text:
Here's a water tracker with a goal of 8 glasses. Tap a glass to add or remove it, and it starts fresh each day.

```page
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Water tracker</title>
<style>
  body { font-family: system-ui, sans-serif; margin: 0; padding: 24px; background: #f2f8fc; color: #12384f; text-align: center; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  #date { font-size: 13px; opacity: .7; margin-bottom: 16px; }
  #count { font-size: 40px; font-weight: 700; margin: 8px 0; }
  #bar { height: 12px; background: #d6e7f2; border-radius: 6px; overflow: hidden; max-width: 320px; margin: 0 auto 20px; }
  #fill { height: 100%; width: 0; background: #2a9df4; transition: width .25s; }
  #glasses { display: grid; grid-template-columns: repeat(4, 64px); gap: 12px; justify-content: center; margin-bottom: 20px; }
  .glass { width: 64px; height: 80px; border: 2px solid #2a9df4; border-radius: 6px 6px 16px 16px; background: #fff; cursor: pointer; font-size: 28px; padding: 0; }
  .glass.full { background: #2a9df4; }
  .row button { font-size: 16px; padding: 8px 18px; margin: 0 4px; border: 0; border-radius: 8px; background: #12384f; color: #fff; cursor: pointer; }
  .row button.light { background: #d6e7f2; color: #12384f; }
  #msg { margin-top: 16px; min-height: 20px; font-weight: 600; }
</style>
</head>
<body>
  <h1>Daily water intake</h1>
  <div id="date"></div>
  <div id="count">0 / 8</div>
  <div id="bar"><div id="fill"></div></div>
  <div id="glasses"></div>
  <div class="row">
    <button class="light" id="minus">− 1 glass</button>
    <button id="plus">+ 1 glass</button>
    <button class="light" id="reset">Reset</button>
  </div>
  <div id="msg"></div>
<script>
  var GOAL = 8;
  var today = new Date().toISOString().slice(0, 10);
  var key = "water-" + today;
  var n = 0;
  try { n = parseInt(localStorage.getItem(key) || "0", 10) || 0; } catch (e) {}
  document.getElementById("date").textContent = new Date().toDateString();

  var wrap = document.getElementById("glasses");
  for (var i = 0; i < GOAL; i++) {
    (function (i) {
      var b = document.createElement("button");
      b.className = "glass";
      b.onclick = function () { n = (n === i + 1) ? i : i + 1; render(); };
      wrap.appendChild(b);
    })(i);
  }

  function render() {
    n = Math.max(0, n);
    try { localStorage.setItem(key, String(n)); } catch (e) {}
    document.getElementById("count").textContent = n + " / " + GOAL;
    document.getElementById("fill").style.width = Math.min(100, n / GOAL * 100) + "%";
    var gs = wrap.children;
    for (var i = 0; i < gs.length; i++) {
      gs[i].className = "glass" + (i < n ? " full" : "");
      gs[i].textContent = i < n ? "💧" : "";
    }
    document.getElementById("msg").textContent =
      n >= GOAL ? "Goal reached. Well done!" : (GOAL - n) + " more to go";
  }

  document.getElementById("plus").onclick = function () { n++; render(); };
  document.getElementById("minus").onclick = function () { n--; render(); };
  document.getElementById("reset").onclick = function () { n = 0; render(); };
  render();
</script>
</body>
</html>
```
